  mount(`<div class="supply-shell"><aside class="supply-side"><b>${ico('building-2')} 平台运营台</b><a href="#staff-account">${ico('layout-dashboard')} 员工工作台</a><a href="#ops/supply">${ico('server')} 供应商引入</a><a class="active" href="#ops/products">${ico('layers')} 模型商品设计</a><a href="#ops/promotions">${ico('gift')} 促销活动</a><small>内部工作空间 · ${esc(staffRoles[staff.role])}</small></aside><div class="supply-content supply-intake-content"><div class="supply-heading"><div><span class="org-kicker">MODEL PRODUCT DESIGN</span><h1>模型商品进度</h1><p>从来源供给到资料、技术、价格与发布，一屏看清每款商品下一步。</p></div>${['platform_admin','finance'].includes(staff.role)&&products.length?btn('设计价格草稿','price-add','','primary'):'<a class="live-button primary" href="#ops/supply">从供应商开始 '+ico('arrow-right')+'</a>'}</div><div class="supply-intake-kpis"><article><small>商品草稿</small><strong>${products.length}</strong><span>关联真实供给档案</span></article><article><small>待技术验收</small><strong>${products.filter(p=>offers.get(p.offer_id)?.readiness?.documents_complete).length}</strong><span>资料完整仍需真实探测</span></article><article><small>价格草稿</small><strong>${latestPrice.size}</strong><span>仅内部方案，尚未审核发布</span></article><article><small>公开销售</small><strong>0</strong><span>销售与调用尚未开放</span></article></div><section class="supply-panel supply-intake-panel"><div class="supply-intake-title"><div><span class="org-kicker">PRODUCT PIPELINE</span><h2>商品清单</h2><p>点击商品前往对应供方的验证与证据详情。</p></div><span>${products.length} 款</span></div><div class="supply-intake-list">${rows||'<div class="supply-empty">还没有客户商品草稿。先建立供应商与供应产品，再设计客户看到的商品。</div>'}</div></section><p class="supply-intake-foot">价格草稿仅供内部讨论，不是公开售价；模型广场仍为能力展示，订单与真实调用未开放。</p></div></div>`);
